<script setup>
import {computed,onMounted,reactive,ref,onBeforeUnmount} from 'vue'
import {api,number} from './api.mjs'
const props=defineProps({stations:{type:Array,default:()=>[]},disabled:Boolean})
const emit=defineEmits(['refresh','error'])
const items=ref([]),working=ref(false),editing=ref(false),step=ref(1),discovery=ref(null),sample=ref(null),message=ref(''),error=ref(''),auth=ref('none'),secret=reactive({user:'',password:'',bearerToken:'',apiKey:'',apiKeyHeader:'X-API-Key'}),queryRows=ref([]),stationRows=ref([]),variableRows=ref([]),qualityRows=ref([]),mappingRows=ref([]),missing=ref('-9999,-99999'),newStations=ref([])
const variables=[['level','水位','m'],['flow','流量','m3/s'],['precipitation','降水','mm'],['temperature','气温','degC'],['evaporation','蒸发','mm'],['area','面积','km2'],['snowWaterEquivalent','雪水当量','mm']]
const units={level:['m','cm'],flow:['m3/s','L/s'],precipitation:['mm','m'],temperature:['degC','K'],evaporation:['mm','m'],area:['km2','m2'],snowWaterEquivalent:['mm','m']}
const names=Object.fromEntries(variables.map(v=>[v[0],v[1]])),labels={http:'HTTP JSON',sqlserver:'SQL Server',mysql:'MySQL / MariaDB'},steps=[['day','日值'],['hour','小时'],['irregular','逐次']]
// SL 323 水情标准表预置模板：选模板后自动填充表名、字段映射
const SL_TEMPLATES=[
 {key:'ST_PPTN_R',label:'ST_PPTN_R 降水量表',table:'ST_PPTN_R',time:'TM',station:'STCD',format:'wide',rows:[{field:'DRP',variable:'precipitation',unit:'mm',step:'hour'},{field:'DYP',variable:'precipitation',unit:'mm',step:'day'}],fields:'TM 时间 · STCD 站码 · DRP 时段降水量 · DYP 日降水量',note:'DRP 的时段长见 INTV 字段；时段不是 1 小时的站点，请在“统计时段”中改设间隔。'},
 {key:'ST_RIVER_R',label:'ST_RIVER_R 河道水情表',table:'ST_RIVER_R',time:'TM',station:'STCD',format:'wide',rows:[{field:'Z',variable:'level',unit:'m',step:'irregular'},{field:'Q',variable:'flow',unit:'m3/s',step:'irregular'}],fields:'TM 时间 · STCD 站码 · Z 水位 · Q 流量'},
 {key:'ST_RSVR_R',label:'ST_RSVR_R 水库（湖泊）水情表',table:'ST_RSVR_R',time:'TM',station:'STCD',format:'wide',rows:[{field:'RZ',variable:'level',unit:'m',step:'irregular'}],fields:'TM 时间 · STCD 站码 · RZ 库（湖）水位'}
]
const slTemplate=ref('')
const template=computed(()=>SL_TEMPLATES.find(t=>t.key===slTemplate.value))
function applySlTemplate(event){const key=event.target.value;if(!key){slTemplate.value='';return}
 const tpl=SL_TEMPLATES.find(t=>t.key===key);if(!tpl)return
 slTemplate.value=key
 form.config.table=tpl.table;form.config.schema=form.config.schema||(form.kind==='mysql'?form.config.database:'dbo')
 form.mapping.time=tpl.time;form.mapping.station=tpl.station;form.mapping.format=tpl.format
 mappingRows.value=tpl.rows.map(r=>({...r}))
 form.mapping.defaults.station=form.mapping.defaults.station||'SLC'
 message.value='已按 '+tpl.label+' 填好表名和字段，读取表结构后请核对'}
const form=reactive({})
const backfill=reactive({id:'',name:'',start:'',end:''})
const replaceCredentials=ref(false)
const columns=computed(()=>discovery.value?.columns||[]),stationOptions=computed(()=>props.stations)
let timer
function reset(value=null){
 replaceCredentials.value=false
 Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,JSON.parse(JSON.stringify(value||{name:'',kind:'sqlserver',enabled:false,intervalMinutes:5,lookbackHours:48,config:{url:'',recordsPath:'',host:'',port:'',database:'',schema:'',table:'',driver:'ODBC Driver 18 for SQL Server',pageParameter:'',pageSizeParameter:'',pageSize:500,firstPage:1,sinceParameter:'',endParameter:''},mapping:{format:'wide',time:'',station:'',timeZone:'Asia/Shanghai',defaults:{station:'SLC',step:'irregular'},columns:[]}})))
 form.config={pageSize:500,firstPage:1,...form.config};form.mapping={format:'wide',timeZone:'Asia/Shanghai',timePosition:'end',defaults:{station:'SLC',step:'irregular'},...form.mapping};form.mapping.defaults={station:'SLC',step:'irregular',...form.mapping.defaults};form.mapping.levelDatum={status:'unverified',name:'',basis:'',...form.mapping.levelDatum};variableRows.value=Object.entries(form.mapping.variableMap||{}).map(([remote,local])=>({remote,local}));qualityRows.value=Object.entries(form.mapping.qualityMap||{}).map(([remote,local])=>({remote,local}))
 Object.assign(secret,{user:'',password:'',bearerToken:'',apiKey:'',apiKeyHeader:'X-API-Key'});auth.value='none';queryRows.value=Object.entries(form.config.query||{}).map(([name,value])=>({name,value}));stationRows.value=Object.entries(form.mapping.stationMap||{}).map(([remote,local])=>({remote,local:typeof local==='object'?local.id:local}));mappingRows.value=(form.mapping.columns||[]).map(v=>({...v}));if(!mappingRows.value.length)mappingRows.value=[{field:'',variable:'level',unit:'m',step:'irregular'}];newStations.value=(form.mapping.stations||[]).map(v=>({...v}));missing.value=(form.mapping.missingValues||[-9999,-99999]).join(',');step.value=1;discovery.value=null;sample.value=null;error.value='';message.value='';editing.value=true
}
function payload(){
 const value=JSON.parse(JSON.stringify(form));value.config.query=Object.fromEntries(queryRows.value.filter(v=>v.name).map(v=>[v.name,v.value]));if(!value.config.port)delete value.config.port
 value.mapping.columns=mappingRows.value.filter(v=>v.field);value.mapping.stationMap=Object.fromEntries(stationRows.value.filter(v=>v.remote&&v.local).map(v=>[v.remote,v.local]));value.mapping.variableMap=Object.fromEntries(variableRows.value.filter(v=>v.remote&&v.local).map(v=>[v.remote,v.local]));value.mapping.qualityMap=Object.fromEntries(qualityRows.value.filter(v=>v.remote!==''&&v.local).map(v=>[v.remote,v.local]));value.mapping.stations=newStations.value.filter(v=>v.id).map(v=>({...v,lon:v.lon===''?null:v.lon==null?null:Number(v.lon),lat:v.lat===''?null:v.lat==null?null:Number(v.lat)}));value.mapping.missingValues=missing.value.split(/[,，\n]/).map(v=>v.trim()).filter(Boolean)
 for(const key of ['station','variable','value','unit','step','quality','periodStart','periodEnd'])if(!value.mapping[key])delete value.mapping[key]
 const credentials={};if(form.kind==='http'){
  if(auth.value==='bearer'&&secret.bearerToken)credentials.bearerToken=secret.bearerToken
  if(auth.value==='apiKey'&&secret.apiKey){credentials.apiKey=secret.apiKey;credentials.apiKeyHeader=secret.apiKeyHeader||'X-API-Key'}
  if(replaceCredentials.value&&auth.value!=='none'&&!Object.keys(credentials).length)throw Error('请填写新凭据，或选择无需认证')
 }else if(form.kind==='mysql'||!form.config.trustedConnection){
  if(replaceCredentials.value&&!secret.user)throw Error('请填写只读账户和对应密码')
  if(secret.user)credentials.user=secret.user;if(secret.password)credentials.password=secret.password
 }
 if(replaceCredentials.value){value.replaceCredentials=true;value.credentials=credentials}
 else if(Object.keys(credentials).length)value.credentials=credentials
 return value
}
async function load(){try{items.value=(await api('data-connections')).connections||[]}catch(e){error.value=e.message}}
async function run(fn){working.value=true;error.value='';message.value='';try{return await fn()}catch(e){error.value=e.message;return null}finally{working.value=false}}
async function inspect(){await run(async()=>{discovery.value=await api('data-connections/discover',payload());message.value=discovery.value.columns.length?'已读取字段和样例。':'请选择数据表后读取字段。';step.value=2})}
function selectTable(event){const table=(discovery.value?.tables||[]).find(value=>JSON.stringify([value.schema,value.table])===event.target.value);form.config.schema=table?.schema||form.config.schema;form.config.table=table?.table||'';discovery.value={...discovery.value,columns:[],samples:[]}}
async function check(){await run(async()=>{const result=await api('data-connections/test',payload());message.value='连接成功 · 样例 '+result.sampleRecords+' 条'})}
async function preview(){await run(async()=>{sample.value=await api('data-connections/preview',payload());step.value=4})}
async function save(){await run(async()=>{const result=await api('data-connections',payload());message.value='连接已保存。';editing.value=false;await load();emit('refresh');return result})}
async function toggle(item){await run(async()=>{await api('data-connections/'+encodeURIComponent(item.id)+'/enabled',{enabled:!item.enabled});await load()})}
async function sync(item){await run(async()=>{await api('data-connections/'+encodeURIComponent(item.id)+'/sync',{});message.value='已提交同步任务，可在任务中心查看进度。';await load();emit('refresh')})}
function openBackfill(item){Object.assign(backfill,{id:item.id,name:item.name,start:'',end:''})}
async function syncPeriod(){await run(async()=>{if(!backfill.start||!backfill.end||backfill.end<backfill.start)throw Error('请填写递增的补取起止时间。');await api('data-connections/'+encodeURIComponent(backfill.id)+'/sync',{start:backfill.start,end:backfill.end});backfill.id='';message.value='已提交指定时段补取，可在任务中心查看进度。';emit('refresh')})}
function variableChanged(row){row.unit=units[row.variable]?.[0]||''}
function addStation(){newStations.value.push({id:'',name:'',kind:'lake',lon:'',lat:''})}
const stamp=value=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'尚未同步'
onMounted(()=>{load();timer=setInterval(()=>{if(!working.value)load()},15000)})
onBeforeUnmount(()=>clearInterval(timer))
</script>
<template>
 <section class="panel connections-panel">
  <div class="panel-title"><h3>现场数据连接</h3><div class="actions"><button :disabled="working" @click="load">刷新</button><button class="primary" :disabled="disabled||working" @click="reset()">添加连接</button></div></div>
  <p class="muted">连接监测接口或只读数据库，按设定频率更新观测资料。</p>
  <div v-if="items.length" class="table-wrap"><table><thead><tr><th>连接</th><th>采集设置</th><th>最近同步 · 北京时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><b>{{item.name}}</b><br><small>{{labels[item.kind]}}</small></td><td>{{item.enabled?'已启用':'已暂停'}} · 每 {{item.intervalMinutes}} 分钟</td><td>{{stamp(item.lastAttemptAt||item.lastSync?.at)}}<br><small v-if="item.lastSync">{{({running:'采集中',succeeded:'成功',failed:'失败',cancelled:'已停止'})[item.lastSync.status]||item.lastSync.status}}<template v-if="item.lastSync.changed!=null"> · 更新 {{item.lastSync.changed}} 条</template>{{item.lastSync.message?' · '+item.lastSync.message:''}}</small><br><small>最近成功：{{stamp(item.lastSuccessAt)}}</small></td><td><div class="actions"><button :disabled="disabled||working" @click="reset(item)">编辑</button><button :disabled="disabled||working" @click="toggle(item)">{{item.enabled?'暂停':'启用'}}</button><button :disabled="disabled||working" @click="sync(item)">立即同步</button><button :disabled="disabled||working" @click="openBackfill(item)">指定时段补取</button></div></td></tr></tbody></table></div>
  <div v-if="backfill.id" class="connection-editor"><h4>{{backfill.name}} · 指定时段补取</h4><div class="connection-grid"><label>开始时间 · 北京时间<input v-model="backfill.start" type="datetime-local"></label><label>结束时间 · 北京时间<input v-model="backfill.end" type="datetime-local"></label></div><div class="actions"><button :disabled="working" @click="backfill.id=''">取消</button><button class="primary" :disabled="working||!backfill.start||!backfill.end" @click="syncPeriod">提交补取</button></div></div>
  <p v-else class="empty">尚未配置现场数据连接。</p>
  <p v-if="message" class="note" role="status">{{message}}</p><p v-if="error" class="message error" role="alert">{{error}}</p>
  <div v-if="editing" class="connection-editor">
   <div class="panel-title"><h4>{{form.id?'编辑连接':'添加连接'}}</h4><button :disabled="working" @click="editing=false">收起</button></div>
   <nav class="workspace-tabs"><button v-for="(label,index) in ['连接数据库','选择数据表','站点与要素对应','预览并保存']" :key="label" :class="{active:step===index+1}" @click="step=index+1">{{index+1}} · {{label}}</button></nav>
   <fieldset :disabled="working||disabled">
    <template v-if="step===1">
     <div class="connection-grid"><label>连接名称<input v-model="form.name" placeholder="例如：现场主站监测"></label><label>来源类型<select v-model="form.kind" @change="discovery=null"><option value="http">HTTP JSON接口</option><option value="sqlserver">SQL Server</option><option value="mysql">MySQL / MariaDB</option></select></label></div>
     <label v-if="form.credentialConfigured" class="checkbox-label"><input v-model="replaceCredentials" type="checkbox">重新填写整套凭据（换电脑或更换认证方式）</label>
     <template v-if="form.kind==='http'"><div class="connection-grid"><label class="span-all">接口地址<input v-model="form.config.url" type="url" placeholder="https://监测服务器/api/observations"></label><label>记录路径<input v-model="form.config.recordsPath" placeholder="例如 data.records；根数组留空"></label><label>认证方式<select v-model="auth"><option value="none">{{form.credentialConfigured&&!replaceCredentials?'沿用已保存凭据':'无需认证'}}</option><option value="bearer">Bearer Token</option><option value="apiKey">API Key请求头</option></select></label><label v-if="auth==='bearer'">Token<input v-model="secret.bearerToken" type="password" autocomplete="new-password"></label><template v-if="auth==='apiKey'"><label>请求头名称<input v-model="secret.apiKeyHeader"></label><label>API Key<input v-model="secret.apiKey" type="password" autocomplete="new-password"></label></template></div>
      <details><summary>分页与时间参数</summary><div class="connection-grid"><label>页码参数<input v-model="form.config.pageParameter" placeholder="例如 page；不分页留空"></label><label>每页条数参数<input v-model="form.config.pageSizeParameter" placeholder="例如 pageSize"></label><label>每页条数<input v-model.number="form.config.pageSize" type="number" min="1"></label><label>起始页<input v-model.number="form.config.firstPage" type="number" min="0"></label><label>起始时间参数<input v-model="form.config.sinceParameter" placeholder="例如 since / startTime"></label><label>结束时间参数<input v-model="form.config.endParameter" placeholder="例如 endTime"></label></div><div v-for="(row,index) in queryRows" :key="index" class="connection-row"><input v-model="row.name" aria-label="查询参数名称" placeholder="其他查询参数"><input v-model="row.value" aria-label="查询参数值" placeholder="参数值"><button @click="queryRows.splice(index,1)">移除</button></div><button @click="queryRows.push({name:'',value:''})">添加查询参数</button></details>
     </template>
     <template v-else>
      <div class="sl-template-row"><label>水情数据库标准表（SL 323）<select :value="slTemplate" @change="applySlTemplate"><option value="">不使用，手动配置</option><option v-for="tpl in SL_TEMPLATES" :key="tpl.key" :value="tpl.key">{{tpl.label}}</option></select></label><small v-if="template">{{template.fields}}<template v-if="template.note"><br>{{template.note}}</template></small><small v-else>水文部门实时雨水情库一般采用 SL 323 标准表结构，选表后字段自动对应。</small></div>
      <div class="connection-grid"><label>服务器地址<input v-model="form.config.host" placeholder="例如 10.12.0.8"></label><label>端口<input v-model.number="form.config.port" type="number" :placeholder="form.kind==='mysql'?'3306':'1433'"></label><label>数据库名<input v-model="form.config.database" placeholder="例如 RWDB"></label><template v-if="!form.config.trustedConnection||form.kind==='mysql'"><label>只读账户<input v-model="secret.user" autocomplete="off" :placeholder="replaceCredentials?'输入新的只读账户':'留空沿用已保存账户'"></label><label>密码<input v-model="secret.password" type="password" autocomplete="new-password" :placeholder="replaceCredentials?'输入对应密码':'留空沿用已保存密码'"></label></template></div>
      <details><summary>高级设置（一般不用改）</summary><div class="connection-grid"><label>架构<input v-model="form.config.schema" :placeholder="form.kind==='mysql'?'与数据库同名':'dbo'"></label><label v-if="form.kind==='sqlserver'">ODBC驱动<input v-model="form.config.driver"><small>默认 Microsoft ODBC Driver 18；也可填本机已安装的驱动名称。</small></label><label v-if="form.kind==='sqlserver'" class="checkbox-label"><input v-model="form.config.trustedConnection" type="checkbox">使用当前Windows账户</label><label v-if="form.kind==='sqlserver'" class="checkbox-label"><input v-model="form.config.trustServerCertificate" type="checkbox">信任现场服务器证书</label></div></details>
     </template>
     <p v-if="form.credentialConfigured" class="muted">{{replaceCredentials?'保存后使用新凭据，保留字段映射与采集进度。':'连接已登记认证凭据，未填写的凭据继续沿用。'}}</p><div class="actions"><button @click="check">测试连接</button><button class="primary" @click="inspect">读取表与字段 →</button></div>
    </template>
    <template v-if="step===2">
     <div v-if="form.kind!=='http'" class="connection-grid"><label>数据表<select :value="form.config.table?JSON.stringify([form.config.schema||(form.kind==='mysql'?form.config.database:'dbo'),form.config.table]):''" @change="selectTable"><option value="">请选择数据表</option><option v-for="table in discovery?.tables||[]" :key="table.schema+'.'+table.table" :value="JSON.stringify([table.schema,table.table])">{{table.schema}}.{{table.table}}</option></select></label><button @click="inspect">读取选定表字段</button></div>
     <p class="muted">{{columns.length?columns.map(v=>v.name).join('、'):'可先读取来源字段；接口仅返回当前点位时，也可在下一步手动填写字段名。'}}</p>
     <div v-if="discovery?.samples?.length" class="table-wrap sample-table"><table><thead><tr><th v-for="column in Object.keys(discovery.samples[0])" :key="column">{{column}}</th></tr></thead><tbody><tr v-for="(row,index) in discovery.samples" :key="index"><td v-for="column in Object.keys(discovery.samples[0])" :key="column">{{typeof row[column]==='object'?JSON.stringify(row[column]):row[column]}}</td></tr></tbody></table></div><div class="actions"><button @click="step=1">← 连接设置</button><button class="primary" @click="step=3">配置字段对应 →</button></div>
    </template>
    <template v-if="step===3">
     <datalist id="connection-fields"><option v-for="column in columns" :key="column.name" :value="column.name"/></datalist>
     <div class="connection-grid"><label>观测时间字段<input v-model="form.mapping.time" list="connection-fields" placeholder="选择或填写时间字段"></label><label>来源时区<select v-model="form.mapping.timeZone"><option value="Asia/Shanghai">北京时间</option><option value="UTC">UTC</option></select></label><label>站点字段<input v-model="form.mapping.station" list="connection-fields" placeholder="单站接口可留空"></label><label>默认站点<select v-model="form.mapping.defaults.station"><option v-for="station in stationOptions" :key="station.id" :value="station.id">{{station.name}}</option><option v-for="station in newStations.filter(v=>v.id)" :key="station.id" :value="station.id">{{station.name||station.id}}</option></select></label><label>表格形式<select v-model="form.mapping.format"><option value="wide">多个观测列（宽表）</option><option value="long">要素、数值分列（长表）</option></select></label><label>缺测代码<input v-model="missing" placeholder="多个代码用逗号分隔"></label></div>
     <template v-if="form.mapping.format==='wide'"><div v-for="(row,index) in mappingRows" :key="index" class="variable-row"><label>观测字段<input v-model="row.field" list="connection-fields"></label><label>要素<select v-model="row.variable" @change="variableChanged(row)"><option v-for="v in variables" :key="v[0]" :value="v[0]">{{v[1]}}</option></select></label><label>单位<select v-model="row.unit"><option v-for="unit in units[row.variable]" :key="unit">{{unit}}</option></select></label><label>时间尺度<select v-model="row.step"><option v-for="s in steps" :key="s[0]" :value="s[0]">{{s[1]}}</option></select></label><button @click="mappingRows.splice(index,1)">移除</button></div><button @click="mappingRows.push({field:'',variable:'precipitation',unit:'mm',step:'hour'})">添加观测列</button></template>
     <div v-else class="connection-grid"><label>数值字段<input v-model="form.mapping.value" list="connection-fields"></label><label>要素字段<input v-model="form.mapping.variable" list="connection-fields" placeholder="单要素可留空"></label><label>默认要素<select v-model="form.mapping.defaults.variable" @change="form.mapping.defaults.unit=units[form.mapping.defaults.variable]?.[0]"><option value="">请选择</option><option v-for="v in variables" :key="v[0]" :value="v[0]">{{v[1]}}</option></select></label><label>单位字段<input v-model="form.mapping.unit" list="connection-fields" placeholder="留空使用默认单位"></label><label>默认单位<input v-model="form.mapping.defaults.unit" placeholder="m / mm / m3/s"></label><label>默认时间尺度<select v-model="form.mapping.defaults.step"><option v-for="s in steps" :key="s[0]" :value="s[0]">{{s[1]}}</option></select></label></div>
     <details v-if="form.mapping.format==='long'"><summary>来源要素名称对应</summary><div v-for="(row,index) in variableRows" :key="index" class="connection-row"><input v-model="row.remote" placeholder="来源要素名称或代码" aria-label="来源要素名称"><select v-model="row.local" aria-label="平台观测要素"><option v-for="v in variables" :key="v[0]" :value="v[0]">{{v[1]}}</option></select><button @click="variableRows.splice(index,1)">移除</button></div><button @click="variableRows.push({remote:'',local:'level'})">添加要素对应</button></details>
     <details open><summary>站码对应（来源站码 → 平台测站）</summary><p class="muted">每个要接入的站点填一行：左侧填数据库中的站码（STCD），右侧选平台测站。未对应的站点不会导入。</p><div v-for="(row,index) in stationRows" :key="index" class="connection-row"><input v-model="row.remote" placeholder="站码 STCD，如 70114200" aria-label="来源站码"><select v-model="row.local" aria-label="平台站点"><option value="">选择平台站点</option><option v-for="s in [...stationOptions,...newStations.filter(v=>v.id)]" :key="s.id" :value="s.id">{{s.name||s.id}}</option></select><button @click="stationRows.splice(index,1)">移除</button></div><button @click="stationRows.push({remote:'',local:''})">添加站码对应</button><div v-for="(station,index) in newStations" :key="index" class="connection-grid new-station"><label>站点编号<input v-model="station.id"></label><label>站点名称<input v-model="station.name"></label><label>站点类型<select v-model="station.kind"><option value="lake">湖泊水位站</option><option value="river">河流站</option><option value="rain">气象站</option></select></label><label>经度 WGS84<input v-model="station.lon" type="number" step="any"></label><label>纬度 WGS84<input v-model="station.lat" type="number" step="any"></label><button @click="newStations.splice(index,1)">移除测站</button></div><details><summary>平台中没有的测站，在这里登记</summary><button @click="addStation">登记新增测站</button></details></details>
     <details><summary>统计时段与质量字段</summary><div class="connection-grid"><label>时段起点字段<input v-model="form.mapping.periodStart" list="connection-fields"></label><label>时段终点字段<input v-model="form.mapping.periodEnd" list="connection-fields"></label><label>无时段字段时的间隔 / 分钟<input v-model.number="form.mapping.intervalMinutes" type="number" min="1" placeholder="例如30；瞬时水位可留空"></label><label>时间标记<select v-model="form.mapping.timePosition"><option value="end">统计区间结束</option><option value="start">统计区间开始</option></select></label><label>质量字段<input v-model="form.mapping.quality" list="connection-fields" placeholder="未配置时由缺测代码判断"></label></div><div v-for="(row,index) in qualityRows" :key="index" class="connection-row"><input v-model="row.remote" placeholder="来源质量代码" aria-label="来源质量代码"><select v-model="row.local" aria-label="平台质量标记"><option value="valid">有效</option><option value="qualified">合格</option><option value="missing">缺测</option><option value="ice_or_stopped">冰情或停测</option></select><button @click="qualityRows.splice(index,1)">移除</button></div><button @click="qualityRows.push({remote:'',local:'valid'})">添加质量代码对应</button></details>
     <details open><summary>水位基准</summary><div class="connection-grid"><label>来源水位与模型基准<select v-model="form.mapping.levelDatum.status"><option value="unverified">待核实，仅作监测展示</option><option value="verified">已核实与模型同基准</option></select></label><label>基准名称<input v-model="form.mapping.levelDatum.name" placeholder="供数方说明的高程基准"></label><label class="span-all">核对依据<input v-model="form.mapping.levelDatum.basis" placeholder="基准说明、联合测量或批准文件"></label></div><p class="muted">使用最新主站水位起报前，须确认本连接水位与模型同基准；确认内容随本连接的来源版本保存。</p></details>
     <div class="actions"><button @click="step=2">← 来源字段</button><button class="primary" @click="preview">检查观测预览 →</button></div>
    </template>
    <template v-if="step===4">
     <div v-if="sample"><p>本次样例 {{sample.sourceRecords}} 条来源记录，整理为 {{sample.records}} 条观测 · {{sample.start?.replace('T',' ')}} 至 {{sample.end?.replace('T',' ')}} · 北京时间</p><p v-if="sample.newStations.length">同步时登记：{{sample.newStations.map(v=>v.name||v.id).join('、')}}</p><div class="table-wrap"><table><thead><tr><th>站点</th><th>要素</th><th>时间</th><th>数值</th><th>质量</th></tr></thead><tbody><tr v-for="(row,index) in sample.samples" :key="index"><td>{{row.station}}</td><td>{{names[row.variable]||row.variable}}</td><td>{{row.time.replace('T',' ')}}</td><td>{{number(row.value,4)}} {{row.unit}}</td><td>{{row.quality==='missing'?'缺测':row.quality}}</td></tr></tbody></table></div></div><p v-else class="note">请先检查观测预览，确认站点、时间、单位和数值。</p>
     <div class="connection-grid"><label>采集间隔 / 分钟<input v-model.number="form.intervalMinutes" type="number" min="1"></label><label>同步时回看 / 小时<input v-model.number="form.lookbackHours" type="number" min="0"></label><label class="checkbox-label"><input v-model="form.enabled" type="checkbox">保存后启用自动采集</label></div><p class="muted">回看时段用于接收来源修订；相同记录跳过，已有观测与资料版本保留。</p><div class="actions"><button @click="step=3">← 字段对应</button><button @click="preview">重新检查预览</button><button class="primary" :disabled="!sample" @click="save">保存连接</button></div>
    </template>
   </fieldset><p v-if="working" class="note" role="status">正在读取与检查，请稍候…</p>
  </div>
 </section>
</template>
